/* Ironlog — the training report: a period of the log summed up as sections,
   as text (the Drive summary, sharing) or HTML (print). Split out of tools.js
   (ROADMAP E17 phase 5) so Drive sync can write the summary without the
   Tools sheet. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { U, daysBetween, esc, fmtDate, fmtSec, nice, rpeToRir, today, wt } from './core.js';
import { exFull, feelWords, fullName, isWarm, keyLeaf, prText, priorityKeys, setText } from './exercises.js';
import { S } from './state.js';
import { historyFor, prsFor } from './stats.js';
import { caliperCalc, measSeries, sessionTotals, vbtEst, vbtMissed, vbtRirText } from './training.js';
/* end imports */

/* ---------------- the report ---------------- */
/* ---------------- coach report (E1) ----------------
   A read-only account of a stretch of training for a coach — no accounts, no
   server, nothing stored. One data pass (reportData) feeds three renderings:
   plain text for a message, a print page for PDF, and JSON. See
   r&d/specs/share-spec.md. */
export function reportData(from, to, opt) {
  const inR = d => d >= from && d <= to;
  const done = S.workouts.filter(wo => wo.status === 'completed' && inR(wo.date))
    .sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
  const wos = done.filter(wo => wo.kind !== 'mobility');
  const weeks = Math.max(1, (daysBetween(from, to) + 1) / 7);
  const tot = wos.map(sessionTotals);
  const mins = wos.map(wo => wo.summary && wo.summary.mins).filter(m => m > 0);
  const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
  const cis = opt.checkins ? S.checkins.filter(c => inR(c.date)).sort((a, b) => a.date < b.date ? -1 : 1) : [];
  const bws = cis.filter(c => c.weight > 0);
  const lifts = priorityKeys().map(k => {
    const h = historyFor(k), now = h.filter(s => inR(s.date)), was = h.filter(s => s.date < from);
    if (!now.length) return null;
    const top = now.reduce((a, b) => b.e1 > a.e1 ? b : a);
    return { name: fullName(keyLeaf(k)), best: top.e1, top, prev: was.length ? Math.max(...was.map(s => s.e1)) : null };
  }).filter(Boolean);
  const vbtNote = s => {
    const v = s.vbt; if (!v) return '';
    const miss = vbtMissed(s);
    return ` [${v.best.toFixed(2)} m/s${v.loss >= 5 ? `, loss ${v.loss.toFixed(0)}%` : ''}${vbtEst(v, s) ? `, bar-speed RIR ${vbtRirText(v.est)}` : ''}${miss ? `, sensor found ${v.reps.length} of ${s.r} reps` : ''}${v.reps && v.reps.length ? `; reps ${v.reps.map(r => r.v.toFixed(2)).join('/')}` : ''}]`;
  };
  const setLine = (e, s) => setText(e, s) + (opt.vbt ? vbtNote(s) : '') + (opt.notes && s.feel && s.feel.note ? ` (“${s.feel.note}”)` : '');
  const sessions = wos.map(wo => {
    const cs = wo.cardio && wo.cardio.summary;
    return {
      date: wo.date, name: wo.name, mins: wo.summary && wo.summary.mins || null,
      note: opt.notes && wo.feel && wo.feel.note || '', flags: feelWords(wo),
      cardio: cs ? [fmtSec(cs.sec || 0), cs.distKm > 0 ? `${cs.distKm.toFixed(2)} km` : '',
        cs.readout && cs.readout.kcal ? `${Math.round(cs.readout.kcal)} kcal` : '', cs.avgHr ? `avg HR ${cs.avgHr}` : ''].filter(Boolean).join(' · ') : '',
      exercises: wo.exercises.map(e => {
        const sets = e.sets.filter(s => s.done !== false && (opt.warm || !isWarm(s)));
        /* runs of the same set collapse: "3 sets of 100kg × 5 @ 2" */
        const runs = [];
        sets.forEach(s => {
          const t = (isWarm(s) ? 'warm-up ' : '') + setLine(e, s), last = runs[runs.length - 1];
          if (last && last.t === t) last.n++; else runs.push({ t, n: 1 });
        });
        return { name: exFull(e), note: opt.notes ? e.notes || '' : '', sets: runs.map(r => r.n > 1 ? `${r.n} sets of ${r.t}` : r.t) };
      }).filter(x => x.sets.length),
    };
  });
  return {
    from, to, made: today(), handle: (S.settings.handle || '').trim(),
    count: wos.length, perWeek: wos.length / weeks, mobility: done.length - wos.length,
    sets: tot.reduce((a, t) => a + t.sets, 0), volume: tot.reduce((a, t) => a + t.volume, 0), mins: avg(mins),
    bw: bws.length ? { first: bws[0].weight, last: bws[bws.length - 1].weight } : null,
    sleep: avg(cis.map(c => c.sleepH).filter(v => v > 0)), energy: avg(cis.map(c => c.energy).filter(v => v > 0)),
    soreness: avg(cis.map(c => c.soreness).filter(v => v > 0)), ciNotes: opt.notes ? cis.filter(c => c.notes).map(c => ({ date: c.date, t: c.notes })) : [],
    lifts, prs: wos.flatMap(wo => prsFor(wo).map(p => ({ date: wo.date, name: p.name, what: prText(p), e1: p.label ? null : p.e1 }))),
    sessions, raw: { sessions: done, checkins: cis },
  };
}
/* Sections as [heading, lines[], isSession] — the text and print renderings
   walk the same list, so they can't drift apart. */
function reportSections(R) {
  const d = s => fmtDate(s, { weekday: 'short', day: 'numeric', month: 'short' });
  const n1 = v => v == null ? '—' : nice(Math.round(v * 10) / 10);
  const feel = [R.sleep ? `sleep ${n1(R.sleep)} h` : '', R.energy ? `energy ${n1(R.energy)}/5` : '', R.soreness ? `soreness ${n1(R.soreness)}/5` : ''].filter(Boolean).join(' · ');
  const sum = [
    `${R.count} session${R.count === 1 ? '' : 's'} (${n1(R.perWeek)} a week)${R.mobility ? ` + ${R.mobility} mobility` : ''}`,
    `${R.sets} working sets · ${wt(R.volume, 0)} volume${R.mins ? ` · ${Math.round(R.mins)} min average` : ''}`,
    R.bw ? `Bodyweight ${wt(R.bw.first)} → ${wt(R.bw.last)}` : '',
    feel ? `Check-ins: ${feel}` : '',
  ].filter(Boolean);
  const out = [['Summary', sum]];
  if (R.lifts.length) out.push(['Main lifts (best estimated 1RM)', R.lifts.map(l =>
    `${l.name}: ${wt(l.best)}${l.prev ? ` (was ${wt(l.prev)}, ${l.best >= l.prev ? '+' : '−'}${wt(Math.abs(l.best - l.prev))})` : ''} · top set ${wt(l.top.w)} × ${l.top.r}${l.top.rpe ? ` @ ${rpeToRir(l.top.rpe)}` : ''}`)]);
  if (R.prs.length) out.push(['Personal records', R.prs.map(p => `${d(p.date)} · ${p.name} ${p.what}${p.e1 ? ` (e1RM ${wt(p.e1)})` : ''}`)]);
  if (R.ciNotes.length) out.push(['Check-in notes', R.ciNotes.map(c => `${d(c.date)}: “${c.t}”`)]);
  R.sessions.forEach(s => out.push([`${d(s.date)} · ${s.name}${s.mins ? ` · ${s.mins} min` : ''}`, [
    ...(s.flags ? [s.flags] : []), ...(s.note ? [`“${s.note}”`] : []), ...(s.cardio ? [s.cardio] : []),
    ...s.exercises.flatMap(e => [`• ${e.name}${e.note ? ` — ${e.note}` : ''}`, ...e.sets.map(t => `   ${t}`)]),
  ], true]));
  return out;
}
function reportHead(R) {
  const long = s => fmtDate(s, { day: 'numeric', month: 'short', year: 'numeric' });
  return [`Training report${R.handle ? ` · ${R.handle}` : ''}`, `${long(R.from)} – ${long(R.to)}`,
    `Weights in ${U()} · "@ 2" means 2 reps in reserve (RIR) · made ${long(R.made)} with Ironlog`];
}
export function reportText(R) {
  const [t, r, k] = reportHead(R);
  return [t.toUpperCase(), r, k, '', ...reportSections(R).flatMap(([h, lines, sess]) => [sess ? h : h.toUpperCase(), ...lines, ''])].join('\n').trim();
}
export function reportHtml(R) {
  const [t, r, k] = reportHead(R);
  return `<h1>${esc(t)}</h1><p class="rp-sub">${esc(r)}<br>${esc(k)}</p>
    ${reportSections(R).map(([h, lines, sess]) => `<section class="${sess ? 'rp-sess' : ''}"><h2>${esc(h)}</h2>
      ${lines.map(l => /^ {3}/.test(l) ? `<div class="rp-set">${esc(l.trim())}</div>` : /^• /.test(l) ? `<div class="rp-ex">${esc(l.slice(2))}</div>` : `<div>${esc(l)}</div>`).join('')}</section>`).join('')}`;
}
/* What's stored, for prefilling. Each is null when there's nothing. */
export function latestBF() {
  const t = [...(S.calipers || [])].sort((a, b) => a.date < b.date ? 1 : -1).map(caliperCalc).find(r => r && r.complete && !r.odd);
  return t ? t.bf : null;
}
export function latestMeasCm(name) {
  const ser = measSeries();
  const k = Object.keys(ser).find(x => x.toLowerCase().replace(/^x:/, '').replace(/\s*\((l|r)\)$/, '') === name);
  const pts = k ? ser[k] : null;
  return pts && pts.length ? pts[pts.length - 1].v : null;
}
